head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.isFirstLoad = false;
scwin.vInitSetting = false;
scwin.vDELIST_DD = '';
scwin.vDELIST_DD_F = '';
scwin.vEXER_END_DD_F = '';
// 세션정보를 얻기위한 함수사용
scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.fr_bz_procs_no = "", scwin.Dd = "";
scwin.trsIdx; // insert, update 구분

scwin.getPar, scwin.setPar;

// 변수 선언

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const fnc = $c.frame.path("../").scwin.getPar; // Provider화면에서 fn_GetPar명칭으로 선언된 함수를 획득
        const arrPar = new Array();
        if (fnc !== undefined) {
            fnc(arrPar); // Provider화면의 callback함수를 호출하여 필요한 인수를 넘겨받는다.
            scwin.Secugrp_id = (arrPar.length >= 1 ? arrPar[0] : ""); // 증권그룹ID
            scwin.Mkt_id = (arrPar.length >= 2 ? arrPar[1] : ""); // 시장구분코드
            scwin.fr_bz_procs_no = (arrPar.length >= 3 ? arrPar[2] : ""); // 업무처리번호(수정시만 유효)
            scwin.Dd = (arrPar.length >= 4 ? arrPar[3] : ""); // 행사종료일(D-30) 또는 당일자

        }
        await scwin.getRsnCd();

        // alert( "Isur_cd =  " +Isur_cd + "\n"  + " Isur_nm = " + Isur_nm + "\n" + "  Secugrp_id = " + Secugrp_id + "\n" +
        //         "Mkt_id =  " +Mkt_id + "\n" + " fr_bz_procs_no = " + fr_bz_procs_no+ "\n"  ) ;

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성

        buttonSet.setCopyInfo(btn_Search, scwin.getIsuCd, btn_Save); // 조회

        edt_WrtDd.setValue(scwin.Dd);
        if (scwin.fr_bz_procs_no !== "") {
            // Provider화면 에서 넘겨받은 업무처리번호가 ""가 아니라면 신규작성으로 간주한다.
            edt_WrtDd.setReadOnly(true);
            await scwin.search();
        } else {
            edt_WrtDd.setReadOnly(false);
            await scwin.newOnload(); // 신규작성시 호출

        }
        $c.libRoundPanel.PanelToGroupBox(panel_3);
        $c.libRoundPanel.PanelToGroupBox(panel_1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05922.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_OnFail
 * @description On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_OnFail = function() {
    try {
        $c.lc.fn_alertMsg('F');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05922.trs_OnFail" });
    }
};

/**
 * @method
 * @name trs_OnSuccess
 * @description On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        if (buttonSet.status === "D") {
            // 삭제처리의 응답인 경우
            await $c.win.closePopup();
        } else {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05922.trs_OnSuccess" });
    }
};

/**
 * @method
 * @name dts_Mst_OnLoadCompleted
 * @description dts_Mst 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.fr_bz_procs_no === "") {
            dts_Mst.insertRow();
        }

        // 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
        if (scwin.fr_bz_procs_no === "") {
            buttonSet.setInsertStatus();
        } else {
            $c.stf.setButtonSetWithDate(edt_MktactNotiDd, false);
        }
        scwin.isFirstLoad = true;
        if (scwin.fr_bz_procs_no === "") {
            cmb_Rsn_Cd.BindColVal = "201";
            txb_GrndRegulContn.setValue(dts_Rsn.getCellData(cmb_Rsn_Cd.getSelectedIndex() + 1, "REGL"));
        } else {
            cmb_Rsn_Cd.BindColVal = dts_Mst.getCellData(dts_Mst.getRowPosition(), "ADVNOTI_RSN_TP_CD");
        }
        scwin.isFirstLoad = false;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05922.dts_Mst_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_CheckDate_OnLoadCompleted
 * @description dts_CheckDate 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_CheckDate_OnLoadCompleted = function(rowcount) {
    try {
        scwin.vDELIST_DD = '';
        if (dts_CheckDate.getRowCount() >= 1) {
            scwin.vDELIST_DD = dts_CheckDate.getCellData(1, "DELIST_DD");
            scwin.vDELIST_DD_F = dts_CheckDate.getCellData(1, "DELIST_DD_F");
            scwin.vEXER_END_DD_F = dts_CheckDate.getCellData(1, "EXER_END_DD_F");
        }
        scwin.setEtcInfo();
        edt_MktactNotiDd.setValue(scwin.vDELIST_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05922.dts_CheckDate_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05922.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name img_DelistDd_onclick
 * @description img_DelistDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_DelistDd_onclick = function() {
    try {
        popUpCalendar2(edt_MktactNotiDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05922.img_DelistDd_onclick" });
    }
};

/**
 * @method
 * @name cmb_Rsn_Cd_onselchange2
 * @description cmb Rsn Cd onselchange2 처리
 * @returns {void}
 * @hidden N
 */
scwin.cmb_Rsn_Cd_onselchange2 = function() {
    try {
        if (scwin.isFirstLoad) return;
        txb_GrndRegulContn.setValue(dts_Rsn.getCellData(cmb_Rsn_Cd.getSelectedIndex() + 1, "REGL"));
        // alert(dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "CODE") + "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "NAME")+ "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "REGL")) ;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05922.cmb_Rsn_Cd_onselchange2" });
    }
};

/**
 * @method
 * @name cmb_Rsn_Cd_OnSelected
 * @description cmb Rsn Cd On Selected 처리
 * @returns {void}
 * @hidden N
 */
scwin.cmb_Rsn_Cd_OnSelected = function() {

};

/**
 * @method
 * @name img_WrtDd_onclick
 * @description img_WrtDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_WrtDd_onclick = function() {
    try {
        if (scwin.fr_bz_procs_no !== "") return;
        popUpCalendar2(edt_WrtDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05922.img_WrtDd_onclick" });
    }
};

/**
 * @method
 * @name dts_Isu_OnLoadCompleted
 * @description dts_Isu 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Isu_OnLoadCompleted = async function(rowcount) {
    try {
        if (scwin.vInitSetting) {
            await scwin.getCheckDD();
            scwin.vInitSetting = false;
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05922.dts_Isu_OnLoadCompleted" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name getCheckDD
 * @description get Check DD 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getCheckDD = async function() {
    const sbmOptions = {
        id : "sbm_dts_CheckDate",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_CheckDate=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name getIsuCd
 * @description get Isu Cd 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getIsuCd = async function() {
    if (edt_WrtDd.text.length !== 8) {
        await $c.win.alert("[행사종료일(D-30)]을 정확히 입력하세요.");
        return false;
    }

    /////////////////////////////
    scwin.vInitSetting = true;
    //////////////////////////

    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/Delisting.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (scwin.fr_bz_procs_no !== "") {
        url += "&SCREN_ID=" + "ULDSTF05922.xml";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
            id : "sbm_dts_Mst",
            action : "/Delisting.do",
            ref : "",
            target : "dts_Mst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions2 = {
            id : "sbm_dts_Isu",
            action : "/Delisting.do",
            ref : "",
            target : "dts_Isu=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name newOnload
 * @description new Onload 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newOnload = async function() {
    url += "&SCREN_ID=" + "ULDSTF05922.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // dts_Mst.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DELLIST_MST_INFO_INOUT";
    const sbmOptions = {
        id : "sbm_dts_Mst",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Mst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name getRsnCd
 * @description get Rsn Cd 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getRsnCd = async function() {
    const sbmOptions = {
        id : "sbm_dts_Rsn",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Rsn=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name saveTrs
 * @description 매매거래정지종목은 매번 업무처리 번호를 세팅함
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveTrs = async function() {
    // 매매거래정지종목은 매번 업무처리 번호를 세팅함
    // 종목별 변경이 있을수 있기 때문
    for (let i = 1; i <= dts_Isu.getRowCount(); i++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        //
        // ********************************************************************

        /*ORG SRC: dts_Isu.NameString(i, "BZ_PROCS_NO") = fr_bz_procs_no;*/
        X = scwin.fr_bz_procs_no;
    }
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "BZ_PROCS_NO", scwin.fr_bz_procs_no);
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "ISUR_CD", "99999");
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "ADVNOTI_RSN_TP_CD", dts_Rsn.getCellData(cmb_Rsn_Cd.getSelectedIndex() + 1, "CODE"));
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "WRT_DD", edt_WrtDd.getValue());
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "INFO_CONTN_TP_CD", "5"); // 5 ELW상장폐지예고

    // alert(dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "CODE") + "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "NAME")+ "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "REGL")) ;

    let vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.trsIdx === TRS_IDX_INSERT) vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.trsIdx === TRS_IDX_DELETE) vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    trs.KeyName = "toinb_dataid4";
    // [전환검토] trs.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : scwin.trsIdx,
    //     BZ_PROCS_NO : scwin.fr_bz_procs_no,
    //     COUNT : "2",
    //     LIST_BZ_TP_CD : LIST_BZ_TP_CD_308 + ",DIV_IDX[0]=" + DIV_IDX_DELLIST_MST_INFO + ",DIV_IDX[1]=" + DIV_IDX_DELLIST_DTL_INFO
    // };
    const sbmOptions = {
        id : "sbm_trs",
        action : "/Delisting.do",
        ref : "dts_Mst,dts_Isu",
        target : "trs=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setEtcInfo
 * @description 기타 안내문 작성 FUNCTION
 * @returns {void}
 * @hidden N
 */
scwin.setEtcInfo = function() {
    let etc = '';
    if (dts_CheckDate.getRowCount() === 1) {
        // etc = '권리행사기간이 만료됨에 따라 상기 주식워런트증권 '+ dts_Isu.CountRow + '종목은 상장폐지될 예정이오니\n투자에 유의하시기 바랍니다.';
        etc = '-';
    } else if (dts_CheckDate.getRowCount() === 2) {
        /*etc = '권리행사기간이 만료됨에 따라 상기 주식워런트증권 '+ dts_Isu.CountRow + '종목은 상장폐지될 예정이오니\n투자에 유의하시기 바랍니다.'
				+ '권리행사기간 만료일이 ' + dts_CheckDate.NameString(1, "EXER_END_DD_F") + '인 ' + dts_CheckDate.NameString(1, "CNT") + '종목은 ' + dts_CheckDate.NameString(1, "DELIST_DD_F")
				+ ',\n '
				+ '권리행사기간 만료일이 ' + dts_CheckDate.NameString(2, "EXER_END_DD_F") + '인 ' + dts_CheckDate.NameString(2, "CNT") + '종목은 ' + dts_CheckDate.NameString(2, "DELIST_DD_F")
				+ '에 \n상장폐지될 예정입니다.';
         */
        etc = '-';
    }
    txa_Remk.text = etc;
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (dts_Isu.getRowCount() === 0) {
        await $c.win.alert("[예고종목]을 선택하세요.");
        return false;
    }
    if (!$c.lc.checkDdTm("DD", edt_MktactNotiDd, "상장폐지", false)) return false;
    if (!$c.stf.checkEmptyValue(txb_GrndRegulContn, "근거규정")) return false;
    if (!$c.stf.checkMaxLength(txb_GrndRegulContn, 200, "근거규정")) return false;
    if (!$c.stf.checkMaxLength(txa_Remk, 2000, "기타")) return false;
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess('I')) return;
        scwin.fr_bz_procs_no = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
        if (scwin.fr_bz_procs_no.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            scwin.trsIdx = TRS_IDX_INSERT;
            await scwin.saveTrs();
        }
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    if (await scwin.checkForm()) {
        scwin.trsIdx = TRS_IDX_UPDATE;
        if (!$c.lc.fn_isProcess('U')) return;
        await scwin.saveTrs();
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    await scwin.saveTrs();
};

/**
 * @method
 * @name dscl
 * @description dscl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    const OldGet = scwin.getPar;
    const OldSet = scwin.setPar;
    scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        arr[0] = "68956C";
        arr[1] = scwin.fr_bz_procs_no;
        arr[2] = "99999";
        arr[3] = '1';

        // jackal_150618
        // 공시제목 추가
        arr[4] = '';
